#!/usr/bin/env python3
import sys, os, re, gzip, csv, io, json
import xml.etree.ElementTree as ET
from fractions import Fraction
from decimal import Decimal, ROUND_HALF_UP
from datetime import date, datetime, timedelta, timezone

KG = {'kg': Fraction(1), 'g': Fraction(1, 1000), 'lb': Fraction(45359237, 10**8),
      'oz': Fraction(28349523125, 10**12)}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
MONTHS = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}


def read_bytes(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] in (b'\xff\xfe', b'\xfe\xff'):
        return b.decode('utf-16')
    head = b[:2000].decode('latin-1')
    m = re.search(r'^#\s*charset\s*:\s*([\w.\-]+)', head, re.M | re.I)
    if m:
        try:
            return b.decode(m.group(1).strip())
        except (LookupError, UnicodeDecodeError):
            pass
    return b.decode('utf-8', errors='replace')


def norm_id(s):
    m = re.search(r'(\d+)', s)
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def counted(s):
    return norm_status(s) in ('delivered', 'delivered_late')


def parse_unit(s, default=None):
    if s:
        m = re.match(r'\s*([A-Za-z]+)', s)
        if m:
            u = m.group(1).lower()
            u = {'kgs': 'kg', 'lbs': 'lb', 'grams': 'g', 'gram': 'g', 'ounces': 'oz'}.get(u, u)
            if u in KG:
                return u
    return default


def parse_num(s, decimal_comma=False):
    s = s.strip()
    if decimal_comma:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Fraction(Decimal(s))


def split_weight(s, decimal_comma=False):
    """value possibly with trailing unit -> (Fraction, unit or None)"""
    s = s.strip()
    m = re.match(r'^(.*?)\s*([A-Za-z]+)$', s)
    unit = None
    if m and m.group(2).lower() in ('kg', 'g', 'lb', 'lbs', 'oz', 'kgs'):
        unit = parse_unit(m.group(2))
        s = m.group(1)
    return parse_num(s, decimal_comma), unit


def parse_date(s, form):
    s = s.strip()
    f = (form or '').strip()
    fl = f.lower()
    if fl in ('iso', 'ymd', 'yyyy-mm-dd'):
        return date.fromisoformat(s[:10])
    if fl in ('dmy', 'dd-mm-yyyy'):
        d, m, y = re.split(r'[-/.]', s)
        return date(int(y), int(m), int(d))
    if fl == 'mm/dd/yyyy':
        m, d, y = s.split('/')
        return date(int(y), int(m), int(d))
    if fl == 'dd/mm/yyyy':
        d, m, y = s.split('/')
        return date(int(y), int(m), int(d))
    if fl == 'dd.mm.yyyy':
        d, m, y = s.split('.')
        return date(int(y), int(m), int(d))
    if fl == 'serial':
        return date(1899, 12, 30) + timedelta(days=int(Fraction(Decimal(s))))
    if fl == 'yyyyddd':
        return date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:7]) - 1)
    if fl == 'yyyymmdd':
        return date(int(s[:4]), int(s[4:6]), int(s[6:8]))
    raise ValueError('date form %r' % f)


def parse_dt_utc(s):
    s = s.strip()
    if 'T' not in s and ' ' not in s:
        return date.fromisoformat(s)
    s = s.replace(' ', 'T', 1)
    if s.endswith(('Z', 'z')):
        s = s[:-1] + '+00:00'
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is not None:
        dt = dt.astimezone(timezone.utc)
    return dt.date()


# record: dict(type, num, date, kg(Fraction), status)

def tmap(t):
    t = (t or '').strip().lower()
    if t in ('c', 'cor', 'corr', 'correction', 'amend'):
        return 'C'
    if t in ('v', 'void'):
        return 'V'
    return 'N'


def logical_lines(text):
    """Yield (is_comment, text) with quoted fields spanning lines joined."""
    buf = None
    for line in text.split('\n'):
        if line.endswith('\r'):
            line = line[:-1]
        if buf is None:
            if not line.strip():
                continue
            if line.startswith('#'):
                yield True, line
                continue
            buf = line
        else:
            buf += '\n' + line
        if buf.count('"') % 2 == 0:
            yield False, buf
            buf = None
    if buf is not None:
        yield False, buf


def split_row(line, delim, quoting):
    if quoting:
        r = list(csv.reader([line], delimiter=delim))
        return r[0] if r else []
    return line.split(delim)


def parse_delimited(text, depot):
    cfg = {
        'east': (',', True, {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'}),
        'lakeside': (',', True, {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'}),
        'harbor': ('|', False, {'rec', 'ref', 'date', 'weight', 'state'}),
        'river': ('\t', False, {'t', 'ref', 'shipped', 'weight', 'status'}),
        'west': (';', False, {'id', 'typ', 'shipped', 'weight', 'status', 'note'}),
    }[depot]
    delim, quoting, cols = cfg
    seq = None
    dirs = {}
    header = None
    out = []
    for is_c, line in logical_lines(text):
        if is_c:
            m = re.match(r'#\s*([^:=]+?)\s*:\s*(.*)$', line)
            if m:
                k = m.group(1).strip().lower()
                dirs[k] = m.group(2).strip()
                if k == 'seq' and seq is None:
                    seq = int(re.sub(r'\D', '', m.group(2)))
            else:
                m = re.match(r'#harbor export seq=(\d+)', line)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        f = split_row(line, delim, quoting)
        if f and all(x.strip().lower() in cols for x in f):
            header = [x.strip().lower() for x in f]
            continue
        if header is None:
            continue
        if f and f[0].strip().upper() == 'TOTAL' and depot == 'east':
            continue
        if not any(x.strip() for x in f):
            continue
        extra_unit = None
        if len(f) > len(header):
            cand = f[-1]
            if parse_unit(cand) and cand.strip().lower() in KG or parse_unit(cand) and re.fullmatch(r'\s*[A-Za-z]+\s*', cand):
                extra_unit = parse_unit(cand)
            f = f[:len(header)]
        elif len(f) < len(header):
            f = f + [''] * (len(header) - len(f))
        row = dict(zip(header, f))
        try:
            rec = build_delim(depot, row, dirs, extra_unit)
        except Exception as e:
            sys.stderr.write('skip row %r: %s\n' % (line[:80], e))
            continue
        if rec:
            out.append(rec)
    return seq, out


def build_delim(depot, row, dirs, extra_unit):
    g = lambda k: (row.get(k) or '').strip()
    if depot == 'east':
        typ, ident, st = tmap(g('type')), g('id'), g('status')
        if typ == 'V':
            return dict(type='V', num=norm_id(ident))
        unit = extra_unit or parse_unit(dirs.get('unit'), 'kg')
        w, u = split_weight(g('gross'))
        unit = u or extra_unit or parse_unit(dirs.get('unit'), 'kg')
        d = parse_date(g('shipped'), dirs.get('dates', 'YMD'))
    elif depot == 'lakeside':
        typ, ident, st = tmap(g('kind')), g('id'), g('status')
        if typ == 'V':
            return dict(type='V', num=norm_id(ident))
        w, u = split_weight(g('gross_kg'))
        unit = u or 'kg'
        d = parse_date(g('shipped'), dirs.get('dates', 'iso'))
    elif depot == 'harbor':
        typ = {'NEW': 'N', 'COR': 'C', 'VOID': 'V'}.get(g('rec').upper(), tmap(g('rec')))
        ident = g('ref')
        if typ == 'V':
            return dict(type='V', num=norm_id(ident))
        st = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled',
              'RET': 'returned', 'HLD': 'held'}.get(g('state').upper(), g('state'))
        w, u = split_weight(g('weight'))
        unit = u or extra_unit or 'kg'
        d = parse_date(g('date'), dirs.get('dates', 'iso'))
    elif depot == 'river':
        typ, ident, st = tmap(g('t')), g('ref'), g('status')
        if typ == 'V':
            return dict(type='V', num=norm_id(ident))
        w, u = split_weight(g('weight'))
        unit = u or extra_unit or parse_unit(dirs.get('weight unit'), 'kg')
        d = parse_date(g('shipped'), dirs.get('date format', 'MM/DD/YYYY'))
    elif depot == 'west':
        typ, ident, st = tmap(g('typ')), g('id'), g('status')
        if typ == 'V':
            return dict(type='V', num=norm_id(ident))
        w, u = split_weight(g('weight'), True)
        unit = u or extra_unit or parse_unit(dirs.get('weight unit'), 'kg')
        d = parse_date(g('shipped'), 'DD.MM.YYYY')
    return dict(type=typ, num=norm_id(ident), date=d, kg=w * KG[unit], status=st)


def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = parse_unit(root.get('weight-unit') or root.get('weight_unit'), 'kg')
    out = []
    for el in root.iter('shipment'):
        typ = tmap(el.get('type'))
        num = norm_id(el.get('id') or (el.findtext('id') or ''))
        if typ == 'V':
            out.append(dict(type='V', num=num))
            continue
        w = el.find('weight')
        unit = parse_unit(w.get('unit'), runit) if w.get('unit') else runit
        val, u = split_weight(w.text or '0')
        unit = u or unit
        sh = el.findtext('shipped')
        if sh is None:
            sh = el.get('shipped')
        sh = sh.strip()
        m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\s+(\d{4})$', sh)
        if m:
            d = date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
        else:
            d = parse_dt_utc(sh)
        out.append(dict(type=typ, num=num, date=d, kg=val * KG[unit],
                        status=el.findtext('status') or ''))
    return seq, out


def parse_json(text):
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if seq is None and 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            typ = tmap(o.get('kind'))
            num = norm_id(str(o.get('id')))
            if typ == 'V':
                out.append(dict(type='V', num=num))
                continue
            wk = [k for k in o if k.lower().startswith('weight')]
            k = wk[0]
            unit = parse_unit(k[len('weight'):].lstrip('_'), None)
            val, u = split_weight(str(o[k]))
            unit = unit or u or 'kg'
            out.append(dict(type=typ, num=num, date=parse_dt_utc(o['shipped_at']),
                            kg=val * KG[unit], status=o.get('status') or ''))
    return seq, out


FW = {
    'FW1': dict(len=42, id=(0, 9), type=(9, 10), ship=(10, 17), w=(17, 25), st=(25, 26),
                dform='yyyyddd', wu=Fraction(1, 1000)),
    'FW2': dict(len=43, type=(0, 1), id=(1, 10), ship=(10, 18), w=(18, 26), st=(26, 27),
                dform='yyyymmdd', wu=Fraction(1, 100)),
    'FW3': dict(len=41, id=(0, 9), ship=(9, 16), type=(16, 17), w=(17, 24), st=(24, 25),
                dform='yyyyddd', wu=KG['lb'] / 10),
}
FWST = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def parse_fixed(text):
    seq = None
    layout = None
    out = []
    bylen = {v['len']: k for k, v in FW.items()}
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if not line.strip():
            continue
        if '\x0c' in line or 'SHIPMENT LISTING' in line:
            continue
        if line.startswith('#LAYOUT'):
            layout = line.split()[1].strip()
            continue
        if line.startswith('#SEQ'):
            if seq is None:
                seq = int(line.split()[1])
            continue
        if line.startswith('#'):
            continue
        name = bylen.get(len(line), layout)
        if name is None:
            continue
        L = FW[name]
        s = lambda k: line[L[k][0]:L[k][1]]
        typ = tmap(s('type'))
        num = norm_id(s('id'))
        if typ == 'V':
            out.append(dict(type='V', num=num))
            continue
        d = parse_date(s('ship'), L['dform'])
        out.append(dict(type=typ, num=num, date=d, kg=int(s('w')) * L['wu'],
                        status=FWST.get(s('st').strip().upper(), s('st'))))
    return seq, out


def parse_file(path, depot):
    b = read_bytes(path)
    if depot == 'central':
        return parse_xml(b)
    text = decode(b)
    if depot == 'north':
        return parse_json(text)
    if depot == 'south':
        return parse_fixed(text)
    return parse_delimited(text, depot)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for fn in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, fn)
        if not os.path.isfile(p):
            continue
        depot = fn.split('-')[0]
        exports.setdefault(depot, [])
        try:
            seq, recs = parse_file(p, depot)
        except Exception as e:
            sys.stderr.write('failed %s: %s\n' % (fn, e))
            continue
        exports[depot].append((seq if seq is not None else -1, fn, recs))
    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        lst.sort(key=lambda x: (x[0], x[1]))
        cur = {}
        for _, _, recs in lst:
            for r in recs:
                n = r['num']
                if r['type'] == 'N':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['type'] == 'C':
                    cur[n] = r
                    corrections += 1
                else:
                    if n in cur:
                        del cur[n]
                    corrections += 1
        current[depot] = cur
    rank = {d: i for i, d in enumerate(ORDER)}
    holders = {}
    for depot, cur in current.items():
        for n in cur:
            holders.setdefault(n, []).append(depot)
    handovers = 0
    depots = {d: [0, Fraction(0)] for d in exports}
    months = {}
    for n, ds in holders.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=lambda x: rank.get(x, 99))
        r = current[d][n]
        if counted(r['status']):
            depots[d][0] += 1
            depots[d][1] += r['kg']
            m = '%04d-%02d' % (r['date'].year, r['date'].month)
            e = months.setdefault(m, [0, Fraction(0)])
            e[0] += 1
            e[1] += r['kg']

    def rnd(x):
        v = Decimal(x.numerator) / Decimal(x.denominator)
        import decimal
        with decimal.localcontext() as c:
            c.prec = 60
            v = Decimal(x.numerator) / Decimal(x.denominator)
